const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2021 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n/**\n * Copyright 2021 Google LLC. All rights reserved.\n */\n\n:host {\n  display: block;\n}\n\n.preview {\n  padding: 12px 16px;\n  border: 1px solid var(--color-details-hairline);\n  color: var(--color-text-primary);\n  font-size: 13px;\n  line-height: 20px;\n  border-radius: 12px;\n  margin: 42px 0;\n  letter-spacing: 0.01em;\n}\n\nh2 {\n  color: var(--color-primary-old);\n  font-size: 13px;\n  line-height: 20px;\n  letter-spacing: 0.01em;\n  margin: 9px 0 14px;\n  display: flex;\n  align-items: center;\n  gap: 5px;\n  font-weight: normal;\n}\n\nh3 {\n  font-size: 13px;\n  line-height: 20px;\n  letter-spacing: 0.04em;\n  color: var(--color-text-primary);\n  margin-bottom: 2px;\n  font-weight: normal;\n}\n\n.preview p {\n  margin-bottom: 24px;\n}\n\n.thumbnail {\n  height: 92px;\n}\n\n.video {\n  display: flex;\n  flex-flow: row wrap;\n  gap: 20px;\n}\n\nx-link { /* stylelint-disable-line selector-type-no-unknown */\n  color: var(--color-primary-old);\n  text-decoration-line: underline;\n}\n\nx-link.quick-start-link { /* stylelint-disable-line selector-type-no-unknown */\n  font-size: 14px;\n  line-height: 22px;\n  letter-spacing: 0.04em;\n}\n\n.video-description {\n  min-width: min-content;\n  flex-basis: min-content;\n  flex-grow: 1;\n}\n\n@media (forced-colors: active) {\n  x-link { /* stylelint-disable-line selector-type-no-unknown */\n    color: linktext;\n  }\n}\n\n/*# sourceURL=panelFeedback.css */\n");export default styles;